#!/usr/bin/env node
/**
 * Scans src/features/&#42; and writes four gitignored generated files. This is the
 * ONLY script every feature-adding PR touches indirectly (by adding an optional
 * file to their own feature folder) — nobody hand-edits a shared list.
 *
 *   - src/core/registry/registry.generated.ts   (from manifest.ts, required)
 *   - src/core/i18n/resources.generated.ts       (from i18n/en.json, optional)
 *   - src/core/http/hosts.generated.ts           (from hosts.ts, optional)
 *   - src/core/storage/migrations.generated.ts   (from migrations.ts, optional)
 *
 * manifest.ts/hosts.ts/migrations.ts are transpiled and executed here directly
 * (no bundler), so they must have no runtime imports beyond what this script can
 * satisfy — type-only imports are fine, they erase at compile time. i18n/en.json
 * files are plain JSON and need no transpilation.
 */
const fs = require("fs");
const path = require("path");
const ts = require("typescript");

const ROOT = path.resolve(__dirname, "..");
const FEATURES_DIR = path.join(ROOT, "src/features");
const BANNER = "// AUTO-GENERATED by tools/gen-registry.js — do not edit by hand.\n";

function listFeatureIds() {
  return fs
    .readdirSync(FEATURES_DIR, { withFileTypes: true })
    .filter((entry) => entry.isDirectory() && entry.name !== "_template")
    .map((entry) => entry.name)
    .sort();
}

/** Transpiles + executes a runtime-import-free TS module and returns its exports. */
function loadModule(filePath) {
  const source = fs.readFileSync(filePath, "utf8");
  const { outputText } = ts.transpileModule(source, {
    compilerOptions: { module: ts.ModuleKind.CommonJS, target: ts.ScriptTarget.ES2019 },
    fileName: filePath,
  });

  const sandboxModule = { exports: {} };
  const fn = new Function("module", "exports", "require", outputText);
  fn(sandboxModule, sandboxModule.exports, () => {
    throw new Error(`${filePath}: must not have runtime imports (type-only imports are fine).`);
  });
  return sandboxModule.exports;
}

function writeGenerated(outFile, body) {
  fs.mkdirSync(path.dirname(outFile), { recursive: true });
  fs.writeFileSync(outFile, BANNER + body);
}

// ---------------------------------------------------------------------------
// 1. Feature registry (manifest.ts -> src/core/registry/registry.generated.ts)
// ---------------------------------------------------------------------------
function genRegistry(featureIds) {
  const manifests = [];
  for (const id of featureIds) {
    const manifestPath = path.join(FEATURES_DIR, id, "manifest.ts");
    if (!fs.existsSync(manifestPath)) {
      console.warn(`[gen-registry] skipping "${id}": no manifest.ts`);
      continue;
    }
    const manifest = loadModule(manifestPath).manifest;
    if (!manifest) throw new Error(`${manifestPath} must export a const named "manifest".`);
    if (manifest.id !== id) {
      throw new Error(`${manifestPath}: manifest.id ("${manifest.id}") must match folder name ("${id}").`);
    }
    manifests.push(manifest);
  }
  manifests.sort((a, b) => a.order - b.order);

  const outFile = path.join(ROOT, "src/core/registry/registry.generated.ts");
  writeGenerated(
    outFile,
    'import type { FeatureManifest } from "./types";\n\n' +
      `export const features: FeatureManifest[] = ${JSON.stringify(manifests, null, 2)};\n`,
  );
  console.log(`[gen-registry] wrote ${manifests.length} feature(s) to ${path.relative(ROOT, outFile)}`);
}

// ---------------------------------------------------------------------------
// 2. i18n resources (i18n/en.json -> src/core/i18n/resources.generated.ts)
// ---------------------------------------------------------------------------
function genI18nResources(featureIds) {
  let merged = {};
  const commonPath = path.join(ROOT, "src/core/i18n/common.en.json");
  if (fs.existsSync(commonPath)) {
    merged = { ...merged, ...JSON.parse(fs.readFileSync(commonPath, "utf8")) };
  }

  for (const id of featureIds) {
    const i18nPath = path.join(FEATURES_DIR, id, "i18n/en.json");
    if (!fs.existsSync(i18nPath)) continue;
    const json = JSON.parse(fs.readFileSync(i18nPath, "utf8"));
    for (const key of Object.keys(json)) {
      if (key in merged) {
        throw new Error(
          `${i18nPath}: top-level key "${key}" collides with another feature's i18n file. ` +
            `Each feature's i18n/en.json must be scoped under its own key.`,
        );
      }
    }
    merged = { ...merged, ...json };
  }

  const outFile = path.join(ROOT, "src/core/i18n/resources.generated.ts");
  writeGenerated(outFile, `export const en = ${JSON.stringify(merged, null, 2)} as const;\n`);
  console.log(`[gen-registry] wrote i18n resources to ${path.relative(ROOT, outFile)}`);
}

// ---------------------------------------------------------------------------
// 3. HTTP host allowlist (hosts.ts -> src/core/http/hosts.generated.ts)
// ---------------------------------------------------------------------------
function genHosts(featureIds) {
  const withHosts = featureIds.filter((id) => fs.existsSync(path.join(FEATURES_DIR, id, "hosts.ts")));

  const imports = withHosts
    .map((id, i) => `import { hosts as _hosts${i} } from "../../features/${id}/hosts";`)
    .join("\n");
  const arrayItems = withHosts.map((_, i) => `_hosts${i}`).join(", ");

  const outFile = path.join(ROOT, "src/core/http/hosts.generated.ts");
  writeGenerated(
    outFile,
    'import { aggregateHosts } from "./aggregateHosts";\n' +
      (imports ? imports + "\n" : "") +
      "\n" +
      `export const featureHosts: string[] = aggregateHosts([${arrayItems}]);\n`,
  );
  console.log(
    `[gen-registry] wrote ${withHosts.length} feature host list(s) to ${path.relative(ROOT, outFile)}`,
  );
}

// ---------------------------------------------------------------------------
// 4. SQLite migrations (migrations.ts -> src/core/storage/migrations.generated.ts)
// ---------------------------------------------------------------------------
function genMigrations(featureIds) {
  const withMigrations = featureIds.filter((id) =>
    fs.existsSync(path.join(FEATURES_DIR, id, "migrations.ts")),
  );

  const imports = withMigrations
    .map((id, i) => `import { migrations as _migrations${i} } from "../../features/${id}/migrations";`)
    .join("\n");
  const arrayItems = withMigrations
    .map((id, i) => `  { featureId: ${JSON.stringify(id)}, migrations: _migrations${i} }`)
    .join(",\n");

  const outFile = path.join(ROOT, "src/core/storage/migrations.generated.ts");
  writeGenerated(
    outFile,
    'import type { FeatureMigrations } from "./migrations";\n' +
      (imports ? imports + "\n" : "") +
      "\n" +
      `export const featureMigrations: FeatureMigrations[] = [\n${arrayItems}\n];\n`,
  );
  console.log(
    `[gen-registry] wrote ${withMigrations.length} feature migration list(s) to ${path.relative(ROOT, outFile)}`,
  );
}

function main() {
  const featureIds = listFeatureIds();
  genRegistry(featureIds);
  genI18nResources(featureIds);
  genHosts(featureIds);
  genMigrations(featureIds);
}

main();
